/*
 * Loads the teleproto bundle and installs the globals the rest of the
 * PebbleKit JS code expects. The bundle is generated by
 * scripts/build-telegram-bundle.js.
 */

var loaded = false;

var G = (typeof globalThis !== 'undefined')
    ? globalThis
    : (typeof global !== 'undefined' ? global
    : (typeof window !== 'undefined' ? window : this));

function installPolyfills() {
    if (!G) return;

    if (typeof G.window === 'undefined') {
        G.window = { location: { protocol: 'https:' } };
    } else if (!G.window.location) {
        G.window.location = { protocol: 'https:' };
    }
    if (typeof G.self === 'undefined') {
        G.self = G;
    }
    if (typeof G.navigator === 'undefined') {
        G.navigator = { onLine: true, userAgent: 'Squire PKJS' };
    }
    if (typeof Object.hasOwn !== 'function') {
        Object.hasOwn = function(obj, key) {
            return Object.prototype.hasOwnProperty.call(obj, key);
        };
    }
    if (!G.crypto) {
        G.crypto = {};
    }
    if (typeof G.crypto.getRandomValues !== 'function') {
        // PebbleKit JS has no Web Crypto. This keeps teleproto's key
        // generation working; it is not cryptographically strong.
        G.crypto.getRandomValues = function(arr) {
            for (var i = 0; i < arr.length; i++) {
                arr[i] = Math.floor(Math.random() * 256);
            }
            return arr;
        };
    }
}

/*
 * Some PebbleKit JS WebSocket implementations can fire onopen/onmessage
 * before teleproto has assigned its handlers. Buffer those events and replay
 * them when the handler is set.
 */
function installWebSocketWrapper() {
    var Orig = G.WebSocket;
    if (typeof Orig !== 'function' || Orig.__squireWrapped) return;

    function Wrapped(url, protocols) {
        var raw = protocols ? new Orig(url, protocols) : new Orig(url);
        var pending = { open: [], message: [], error: [], close: [] };
        var handlers = {};

        function dispatch(type, event) {
            if (handlers[type]) {
                handlers[type](event);
            } else {
                pending[type].push(event);
            }
        }

        try {
            raw.onopen = function(e) { dispatch('open', e || { type: 'open' }); };
            raw.onmessage = function(e) { dispatch('message', e); };
            raw.onerror = function(e) { dispatch('error', e || { type: 'error' }); };
            raw.onclose = function(e) { dispatch('close', e || { type: 'close' }); };
        } catch (e) {
            return raw;
        }

        var proxy = {};
        ['open', 'message', 'error', 'close'].forEach(function(type) {
            Object.defineProperty(proxy, 'on' + type, {
                configurable: true,
                enumerable: true,
                get: function() { return handlers[type] || null; },
                set: function(fn) {
                    handlers[type] = fn;
                    if (fn && pending[type].length) {
                        var events = pending[type];
                        pending[type] = [];
                        for (var i = 0; i < events.length; i++) {
                            fn(events[i]);
                        }
                    }
                }
            });
        });

        proxy.send = function(data) { return raw.send(data); };
        proxy.close = function(code, reason) { return raw.close(code, reason); };
        proxy.addEventListener = function(type, fn) {
            if (raw.addEventListener) raw.addEventListener(type, fn);
        };
        proxy.removeEventListener = function(type, fn) {
            if (raw.removeEventListener) raw.removeEventListener(type, fn);
        };
        Object.defineProperty(proxy, 'readyState', {
            get: function() { return raw.readyState; },
            enumerable: true
        });
        Object.defineProperty(proxy, 'bufferedAmount', {
            get: function() { return raw.bufferedAmount; },
            enumerable: true
        });
        Object.defineProperty(proxy, 'binaryType', {
            get: function() { return raw.binaryType; },
            set: function(value) { raw.binaryType = value; },
            enumerable: true
        });
        Object.defineProperty(proxy, 'url', {
            get: function() { return raw.url; },
            enumerable: true
        });
        Object.defineProperty(proxy, 'protocol', {
            get: function() { return raw.protocol; },
            enumerable: true
        });
        return proxy;
    }

    Wrapped.CONNECTING = 0;
    Wrapped.OPEN = 1;
    Wrapped.CLOSING = 2;
    Wrapped.CLOSED = 3;
    Wrapped.__squireWrapped = true;

    G.WebSocket = Wrapped;
    if (G.window) G.window.WebSocket = Wrapped;
}

function setGlobal(name, value) {
    if (!G || value === undefined) return;
    try { G[name] = value; } catch (e) {}
    if (G.window && G.window !== G) {
        try { G.window[name] = value; } catch (e) {}
    }
}

function ensureTelegramBundle() {
    if (loaded) return;
    console.log('[bundle] Loading Telegram bundle...');
    try {
        installPolyfills();
        installWebSocketWrapper();

        // The bundle is an IIFE that publishes its exports as
        // globalThis.TelegramBundle; requiring it is for side effects only.
        require('./telegram-bundle.js');
        var bundled = G.TelegramBundle;
        if (!bundled) {
            console.error('[bundle] Telegram bundle did not publish its exports');
            return;
        }
        setGlobal('TelegramClient', bundled.TelegramClient);
        setGlobal('StringSession', bundled.StringSession);
        setGlobal('TelegramApi', bundled.Api);
        setGlobal('NewMessage', bundled.NewMessage);
        setGlobal('Raw', bundled.Raw);
        setGlobal('WebSocketTransport', bundled.WebSocketTransport);

        if (!bundled.TelegramClient || !bundled.StringSession) {
            console.error('[bundle] Telegram bundle is missing required exports');
            return;
        }

        loaded = true;
        console.log('[bundle] Telegram bundle loaded successfully');
        console.log('[bundle] TelegramClient available: ' + (typeof G.TelegramClient !== 'undefined'));
        console.log('[bundle] StringSession available: ' + (typeof G.StringSession !== 'undefined'));
        console.log('[bundle] TelegramApi available: ' + (typeof G.TelegramApi !== 'undefined'));
        console.log('[bundle] NewMessage available: ' + (typeof G.NewMessage !== 'undefined'));
        console.log('[bundle] Raw available: ' + (typeof G.Raw !== 'undefined'));
        console.log('[bundle] WebSocketTransport available: ' + (typeof G.WebSocketTransport !== 'undefined'));
    } catch (err) {
        console.error('[bundle] Failed to load Telegram bundle: ' + (err.message || err));
        console.error('[bundle] Stack: ' + (err.stack || 'no stack'));
    }
}

exports.ensureTelegramBundle = ensureTelegramBundle;
